@Import({HrmPayrollInsuranceAdjustmentService.class,org.springframework.boot.autoconfigure.validation.ValidationAutoConfiguration.class})
class HrmPayrollInsuranceAdjustmentServiceTest extends BaseDbUnitTest {
 @Resource HrmPayrollInsuranceAdjustmentService service;
 @Resource HrmPayrollInsuranceAdjustmentMapper adjustments;
 @Resource HrmPayrollInsuranceBillMapper bills;
 @Resource HrmPayrollInsuranceBillLineMapper lines;
 @Resource HrmPayrollTaxCorrectionMapper corrections;
 @Resource HrmPayrollTaxPolicyMapper policies;
 @Resource HrmPayrollPaymentMapper payments;
 @Resource HrmPayrollRunMapper runs;
 @Resource HrmEmployeeMapper employees;
 @Resource HrmSalaryMonthRecordMapper batches;
 @MockBean HrmPayrollScopeService scope;
 @MockBean HrmPayrollEntityService entities;
 @MockBean HrmPayrollTaxProfileService profiles;
 HrmSalaryMonthRecordDO original;HrmPayrollPaymentDO payment;HrmPayrollRunDO run;HrmPayrollTaxCorrectionDO correction;Long employeeId;HrmPayrollTaxPolicyDO policy;
 HrmPayrollInsuranceBillDO bill;HrmPayrollInsuranceBillLineDO line;
 BigDecimal n(String value){return new BigDecimal(value);}
 LocalDate today(){return LocalDate.now(ZoneId.of("Asia/Shanghai"));}
 HrmSalaryMonthEmployeeRecordDO salary(String income,String net,int year){List<HrmSalaryMonthEmployeeRecordDO.OptionValue> values=new ArrayList<>();int[] codes={250101,270101,250102,270102,250103,270103};String[] amounts={"0",income,"0","5000","0","1000"};for(int i=0;i<codes.length;i++)values.add(new HrmSalaryMonthEmployeeRecordDO.OptionValue().setCode(codes[i]).setValue(n(amounts[i])));HrmPayrollTaxWithholdingService.Source source=new HrmPayrollTaxWithholdingService.Source().setEntityId(10L).setEmployeeId(employeeId).setCurrentIncome(n(income)).setCurrentSocialDeduction(n("1000")).setExpectedPaymentDate(LocalDate.of(year,9,30)).setProfile(new HrmPayrollTaxProfileDO().setId(100L).setTaxpayerKey("recovery-person").setTaxRegistrationNumber("tax-agent")).setQuote(new PayrollTaxPolicyEngine.Quote().setCurrentSalaryWithholding(n("100")).setCurrentWithholding(n("100")).setSeparateBonusTax(BigDecimal.ZERO));return new HrmSalaryMonthEmployeeRecordDO().setEmployeeId(employeeId).setExpectedPaySalary(n(income)).setRealPaySalary(n(net)).setPersonalTax(n("100")).setOptionValues(values).setTaxSourceSnapshot(JsonUtils.toJsonString(source));}
 @BeforeEach void setup(){HrmEmployeeDO employee=new HrmEmployeeDO().setName("已离职收回员工").setUserId(99L).setJobNumber("REC-1").setLeaveTime(LocalDate.of(2025,9,30).atStartOfDay());employees.insert(employee);employeeId=employee.getId();original=new HrmSalaryMonthRecordDO().setEntityId(10L).setTitle("2025年9月原工资").setYear(2025).setMonth(9).setBatchKey("REGULAR").setStatus(17).setStartTime(LocalDate.of(2025,9,1).atStartOfDay()).setEndTime(LocalDate.of(2025,9,30).atStartOfDay());batches.insert(original);run=new HrmPayrollRunDO().setMonthRecordId(original.getId()).setVersion(1).setInputSnapshot("{}").setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(salary("10000","8900",2025))));runs.insert(run);payment=new HrmPayrollPaymentDO().setMonthRecordId(original.getId()).setRunId(run.getId()).setEmployeeId(employeeId).setEmployeeName("已离职收回员工").setBankAccount("test-bank-fact").setAmount(n("8900")).setStatus("SUCCESS").setAttempt(1).setValueDate(LocalDate.of(2025,9,30));payments.insert(payment);payment=payments.selectById(payment.getId());
  policy=new HrmPayrollTaxPolicyDO().setEntityId(10L).setYear(2025).setTaxRegistrationNumber("tax-agent").setStatus("APPROVED").setVersion(1);policies.insert(policy);when(profiles.requireApproved(eq(10L),eq(employeeId),anyInt())).thenAnswer(call->new HrmPayrollTaxProfileDO().setId(100L).setVersion(1).setTaxpayerKey("recovery-person").setTaxRegistrationNumber("tax-agent").setYear(call.getArgument(2)));
  correction=new HrmPayrollTaxCorrectionDO().setPaymentId(payment.getId()).setEntityId(10L).setEmployeeId(employeeId).setRunId(run.getId()).setVersion(1).setPolicyId(policy.getId()).setPolicyVersion(1).setProfileId(100L).setProfileVersion(1).setTaxpayerKey("recovery-person").setTaxRegistrationNumber("tax-agent").setStatus("APPROVED").setIncome(n("10000")).setSocialDeduction(n("1200")).setBasicDeduction(n("5000")).setActualSalaryWithheld(n("100")).setSeparateBonusIncome(BigDecimal.ZERO).setActualBonusWithheld(BigDecimal.ZERO).setValueDate(payment.getValueDate()).setSourceDigest(HrmPayrollTaxCorrectionService.digest(payment,run));corrections.insert(correction);
  HrmPayrollInsurancePolicyService.ProjectAmount project=new HrmPayrollInsurancePolicyService.ProjectAmount().setCode("PENSION").setPersonalAmount(n("1000")).setCorporateAmount(n("2000"));
  HrmPayrollInsurancePolicyService.Quote q=new HrmPayrollInsurancePolicyService.Quote().setEntityId(10L).setPayerEntityId(10L).setEmployeeId(employeeId).setYear(2025).setMonth(8).setCoverage("INSURED").setPersonalInsurance(n("1000")).setCorporateInsurance(n("2000")).setProjects(Collections.singletonList(project));
  run.setInputSnapshot(JsonUtils.toJsonString(Collections.singletonMap("insurancePolicySources",Collections.singletonMap(employeeId,q))));runs.updateById(run);correction.setSourceDigest(HrmPayrollTaxCorrectionService.digest(payment,runs.selectById(run.getId())));corrections.updateById(correction);
  bill=new HrmPayrollInsuranceBillDO().setEntityId(10L).setYear(2025).setMonth(8).setVersion(1).setStatus("RECONCILED").setReviewedBy(20L).setApprovedBy(30L);bills.insert(bill);
  line=new HrmPayrollInsuranceBillLineDO().setBillId(bill.getId()).setEntityId(10L).setEmployeeId(employeeId).setRevision(1L).setProjectCode("PENSION").setStatus("MATCHED").setExpectedPersonal(n("1200")).setActualPersonal(n("1200")).setExpectedCorporate(n("2500")).setActualCorporate(n("2500"));lines.insert(line);
 }
 HrmPayrollInsuranceAdjustmentReqVO req(){return new HrmPayrollInsuranceAdjustmentReqVO().setPaymentId(payment.getId()).setBillId(bill.getId()).setCorrectionId(correction.getId()).setEmployeeAcknowledgement("员工确认历史个人差额，税款另行核定").setEvidence("已批准最终缴费账单").setRequestKey(UUID.randomUUID().toString());}
 Long approved(){Long id=service.create(req(),1L);service.review(id,true,"独立核实差额",2L);return id;}
 HrmPayrollInsuranceAdjustmentActionReqVO receipt(Long id){return new HrmPayrollInsuranceAdjustmentActionReqVO().setId(id).setAmount(n("200")).setValueDate(today()).setReference("actual-insurance-receipt").setEvidence("个人收款真实银行凭证");}
 @Test void departedEmployeeOriginalContributionMonthAndCashYearRemainImmutable(){String frozen=runs.selectById(run.getId()).getResultSnapshot();Long id=approved();service.confirm(receipt(id),3L);HrmPayrollInsuranceAdjustmentDO a=adjustments.selectById(id);assertEquals("SETTLED",a.getStatus());assertEquals(0,n("200").compareTo(a.getPersonalDelta()));assertEquals(0,n("500").compareTo(a.getCorporateDelta()));assertEquals(frozen,runs.selectById(run.getId()).getResultSnapshot());assertEquals(0,n("8900").compareTo(payments.selectById(payment.getId()).getAmount()));assertEquals(3,service.history(id,1L).size());assertEquals(8,JsonUtils.parseObject(a.getSourceSnapshot(),HrmPayrollInsuranceAdjustmentService.Proof.class).getOriginal().getMonth());}
 @Test void refundHasSignedPersonalAndEmployerAmounts(){line.setExpectedPersonal(n("800")).setActualPersonal(n("800")).setExpectedCorporate(n("1700")).setActualCorporate(n("1700"));lines.updateById(line);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setSocialDeduction(n("800")));Long id=approved();service.confirm(receipt(id).setEvidence("真实退款付款凭证"),3L);assertEquals(0,n("-200").compareTo(adjustments.selectById(id).getPersonalDelta()));assertEquals(0,n("-300").compareTo(adjustments.selectById(id).getCorporateDelta()));assertEquals("REFUND",service.history(id,1L).get(2).getAction());}
 @Test void employerOnlyUsesExplicitZeroAccountingConfirmation(){line.setActualPersonal(n("1000")).setExpectedPersonal(n("1000"));lines.updateById(line);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setSocialDeduction(n("1000")));Long id=approved();service.confirm(receipt(id).setAmount(BigDecimal.ZERO).setEvidence("单位补缴历史成本记账凭证；个人无收退"),3L);assertEquals("CONFIRM_COST",service.history(id,1L).get(2).getAction());}
 @Test void formalOriginalYearDeductionMustEqualCumulativePersonalCorrection(){corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setSocialDeduction(n("1100")));assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);assertTrue(adjustments.selectList().isEmpty());}
 @Test void incompleteAgencyBillCannotFundWageAdjustment(){bills.updateById(new HrmPayrollInsuranceBillDO().setId(bill.getId()).setStatus("APPROVED"));assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);}
 @Test void lineMustRemainReconciledAndRevisionBoundAtApproval(){Long id=service.create(req(),1L);lines.updateById(new HrmPayrollInsuranceBillLineDO().setId(line.getId()).setRevision(2L));assertServiceException(()->service.review(id,true,"核实",2L),PAYROLL_VERSION_CONFLICT);assertEquals("PENDING",adjustments.selectById(id).getStatus());}
 @Test void latestApprovedAgencyVersionMakesOldRequestStale(){Long id=service.create(req(),1L);bills.insert(new HrmPayrollInsuranceBillDO().setEntityId(10L).setYear(2025).setMonth(8).setVersion(2).setStatus("APPROVED"));assertServiceException(()->service.review(id,true,"核实",2L),PAYROLL_VERSION_CONFLICT);}
 @Test void noDuplicateActiveCaseOrReusedSource(){Long id=approved();assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);service.confirm(receipt(id),3L);assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);}
 @Test void makerEmployeeAndReviewerCannotSelfConfirm(){Long id=service.create(req(),1L);assertServiceException(()->service.review(id,true,"本人",1L),PAYROLL_SELF_APPROVAL);assertServiceException(()->service.review(id,true,"本人",99L),PAYROLL_SELF_APPROVAL);service.review(id,true,"独立复核",2L);for(Long actor:Arrays.asList(1L,2L,99L))assertServiceException(()->service.confirm(receipt(id),actor),PAYROLL_SELF_APPROVAL);}
 @Test void wrongReceiptAmountDateOrRetryCannotChangeSettledFacts(){Long id=approved();assertServiceException(()->service.confirm(receipt(id).setAmount(n("100")),3L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);assertServiceException(()->service.confirm(receipt(id).setValueDate(today().plusDays(1)),3L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);service.confirm(receipt(id),3L);service.confirm(receipt(id),3L);assertEquals(3,service.history(id,1L).size());assertServiceException(()->service.confirm(receipt(id).setEvidence("另一个凭证"),3L),PAYROLL_VERSION_CONFLICT);assertServiceException(()->service.cancel(id,"撤销","作废",2L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);}
 @Test void laterFinalBillOnlyAdjustsUnsettledIncrement(){Long first=approved();service.confirm(receipt(first),3L);bills.updateById(new HrmPayrollInsuranceBillDO().setId(bill.getId()).setVersion(2));line.setActualPersonal(n("1300")).setExpectedPersonal(n("1300")).setActualCorporate(n("2700")).setExpectedCorporate(n("2700")).setRevision(2L);lines.updateById(line);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setSocialDeduction(n("1300")));Long second=approved();assertEquals(0,n("100").compareTo(adjustments.selectById(second).getPersonalDelta()));assertEquals(0,n("200").compareTo(adjustments.selectById(second).getCorporateDelta()));assertServiceException(()->service.confirm(receipt(second).setAmount(n("100")),3L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);service.confirm(receipt(second).setAmount(n("100")).setReference("second-receipt"),3L);}
 @Test void crossEntityAndMissingOriginalProjectCannotUseBill(){bills.updateById(new HrmPayrollInsuranceBillDO().setId(bill.getId()).setEntityId(20L));assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);bills.updateById(new HrmPayrollInsuranceBillDO().setId(bill.getId()).setEntityId(10L));lines.updateById(new HrmPayrollInsuranceBillLineDO().setId(line.getId()).setProjectCode("OTHER"));assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);}
 @Test void exactCreateRetryReturnsOneCase(){HrmPayrollInsuranceAdjustmentReqVO request=req();Long id=service.create(request,1L);assertEquals(id,service.create(request,1L));assertEquals(1,adjustments.selectCount());assertServiceException(()->service.create(request.setEvidence("different"),1L),PAYROLL_VERSION_CONFLICT);}
 @Test void unchangedPersonalDeductionNeedsNoNewTaxAmendment(){line.setActualPersonal(n("1000")).setExpectedPersonal(n("1000"));lines.updateById(line);corrections.deleteById(correction.getId());Long id=service.create(req().setCorrectionId(null),1L);assertEquals(0,adjustments.selectById(id).getPersonalDelta().signum());}
 @Test void unapprovedOrStaleTaxProofCannotFundEmployeeDifference(){corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("SUPERSEDED"));assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("APPROVED").setSourceDigest("changed-original"));assertServiceException(()->service.create(req(),1L),PAYROLL_INSURANCE_ADJUSTMENT_INVALID);}
 @Test void concurrentRequestsCannotCollectTheSamePersonalDifferenceTwice() throws Exception {java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newFixedThreadPool(2);java.util.concurrent.Callable<Boolean> submit=()->{try{service.create(req(),1L);return true;}catch(cn.iocoder.yudao.framework.common.exception.ServiceException conflict){assertEquals(PAYROLL_INSURANCE_ADJUSTMENT_INVALID.getCode(),conflict.getCode());return false;}};try{java.util.concurrent.Future<Boolean> a=executor.submit(submit),b=executor.submit(submit);assertNotEquals(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals(1,adjustments.selectCount());}finally{executor.shutdownNow();}}
}
